"""Acceptance tests for escaping text embedded in HTML."""

import sys
from pathlib import Path

import pytest


sys.path.insert(0, str(Path(__file__).parents[1] / "src"))

from sitegen.escape import escape


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("&", "&amp;"),
        ("<", "&lt;"),
        (">", "&gt;"),
        ('"', "&quot;"),
        ("'", "&#x27;"),
    ],
)
def test_escape_replaces_html_special_characters(text: str, expected: str) -> None:
    assert escape(text) == expected


def test_escape_leaves_ordinary_text_unchanged() -> None:
    text = "Hello, world! 123"

    assert escape(text) == text


def test_escape_replaces_special_characters_without_changing_surrounding_text() -> None:
    assert escape('Tom & <Jerry> said "it\'s fine".') == (
        "Tom &amp; &lt;Jerry&gt; said &quot;it&#x27;s fine&quot;."
    )
"""Acceptance tests for the supported Markdown-to-HTML renderer."""

import sys
from pathlib import Path

import pytest


sys.path.insert(0, str(Path(__file__).parents[1] / "src"))

from sitegen.markdown import render


@pytest.mark.parametrize(
    ("markdown", "expected"),
    [
        ("# First level", "<h1>First level</h1>"),
        ("## Second level", "<h2>Second level</h2>"),
        ("### Third level", "<h3>Third level</h3>"),
    ],
)
def test_atx_headings_render_at_the_corresponding_level(
    markdown: str, expected: str
) -> None:
    assert render(markdown) == expected


def test_blank_lines_separate_paragraphs() -> None:
    markdown = "First paragraph.\n\nSecond paragraph."

    assert render(markdown) == "<p>First paragraph.</p>\n<p>Second paragraph.</p>"


def test_unordered_list_renders_as_one_list_with_list_items() -> None:
    markdown = "- apples\n- bananas\n- cherries"

    assert render(markdown) == (
        "<ul>\n<li>apples</li>\n<li>bananas</li>\n<li>cherries</li>\n</ul>"
    )


def test_emphasis_and_strong_text_render_inside_a_paragraph() -> None:
    assert render("Use *emphasis* and **strong text**.") == (
        "<p>Use <em>emphasis</em> and <strong>strong text</strong>.</p>"
    )


def test_inline_code_renders_inside_a_paragraph() -> None:
    assert render("Run `sitegen build` now.") == (
        "<p>Run <code>sitegen build</code> now.</p>"
    )


def test_link_renders_with_its_text_and_target() -> None:
    assert render("Visit [Example](https://example.com/docs).") == (
        '<p>Visit <a href="https://example.com/docs">Example</a>.</p>'
    )


def test_html_special_characters_in_text_are_escaped() -> None:
    assert render("Tom & <Jerry> said \"it's safe\".") == (
        "<p>Tom &amp; &lt;Jerry&gt; said &quot;it&#x27;s safe&quot;.</p>"
    )


def test_markdown_page_link_target_is_rewritten_to_html() -> None:
    assert render("Read [About us](about.md).") == (
        '<p>Read <a href="about.html">About us</a>.</p>'
    )
"""Utilities for safely embedding text in HTML."""


_HTML_ENTITIES = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#x27;",
}


def escape(text: str) -> str:
    """Return *text* with HTML special characters replaced by entities."""
    return "".join(_HTML_ENTITIES.get(character, character) for character in text)
